function resolutionValid(state, gap, allowRedacted = false) {
    if (!gap.resolution)
        return false;
    const evidence = gap.resolution.evidenceIds.map(id => state.evidence.find(item => item.id === id));
    if (!evidence.every(item => item.validity === 'current' && (allowRedacted || !item.passageUnavailable)))
        return false;
    if (gap.resolution.reason === 'not_applicable')
        return evidence.every(item => gap.claimIds.length ? gap.claimIds.every(id => state.claims.find(claim => claim.id === id).scope === item.scope) :
            gap.triggerRefs.includes(item.id) || (gap.triggerRefs.some(ref => ref.startsWith('task:')) && state.task.evidence.some(original => original.id === item.id)));
    const expected = gap.resolution.reason === 'supported' ? 'supported' : 'contradicted';
    if (!gap.claimIds.length)
        return false;
    return gap.claimIds.every(id => {
        const claim = state.claims.find(item => item.id === id);
        const redactedResolution = allowRedacted && evidence.some(item => item.passageUnavailable);
        if (redactedResolution && !state.assessmentCorrections?.length)
            return claim.status === expected;
        return (redactedResolution ? claim.status : claimStatus(state, claim)) === expected && claim.assessments.some(assessment => assessment.verdict === (expected === 'supported' ? 'supports' : 'refutes') && effectiveAssessment(state, assessment, redactedResolution) &&
            assessment.evidenceIds.every(ref => gap.resolution.evidenceIds.includes(ref)));
    });
}
